    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "SSE (Sum of Squared Error), also known as scatter, is a measure of clustering quality calculated by summing the squared Euclidean distances from each data point to its closest centroid.",
    "supporting_evidence_ids": [
      "E2",
      "E7"
    ],
    "supporting_lanes": [
      "context_lane"
