  "scope": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "SSE is used as an objective function to evaluate clustering quality, where a lower SSE indicates that the centroids are a better representation of the points in their cluster and that the clustering results are improved.",
